"""Embedded compiled React SPA bundle for single-port Python production serving."""

import base64
import mimetypes
from typing import Optional, Tuple

FRONTEND_BUNDLE = {'/assets/index-DRIvc_kU.css': '', '/assets/index-_B_WN7WB.js': '', '/index.html': ''}
EMBEDDED_FRONTEND = FRONTEND_BUNDLE


def get_embedded_asset(path: str) -> Optional[Tuple[bytes, str]]:
    clean = "/" + (path or "").lstrip("/")
    if clean == "/":
        clean = "/index.html"
    b64 = FRONTEND_BUNDLE.get(clean)
    if not b64 and clean.startswith("/assets/"):
        ext = ".js" if clean.endswith(".js") else (".css" if clean.endswith(".css") else "")
        if ext:
            for k, v in FRONTEND_BUNDLE.items():
                if k.startswith("/assets/index-") and k.endswith(ext):
                    b64 = v
                    clean = k
                    break
    if not b64:
        return None
    mime, _ = mimetypes.guess_type(clean)
    if clean.endswith(".js"):
        mime = "application/javascript; charset=utf-8"
    elif clean.endswith(".css"):
        mime = "text/css; charset=utf-8"
    elif clean.endswith(".html"):
        mime = "text/html; charset=utf-8"
    return base64.b64decode(b64), (mime or "application/octet-stream")
